def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_from(*keys, default=(0, 0)):
        for k in keys:
            v = observation.get(k)
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by(items, score_fn):
        best_item = None
        best_score = None
        for it in items:
            try:
                s = score_fn(it)
            except Exception:
                continue
            if best_item is None or s < best_score:
                best_item = it
                best_score = s
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos_from("self_position", "position", "self_pos")
    ox, oy = pos_from("opponent_position", "enemy_position", "opponent_pos", default=(sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    grid_w = observation.get("grid_width", observation.get("width", 0))
    grid_h = observation.get("grid_height", observation.get("height", 0))
    center = (grid_w // 2, grid_h // 2) if grid_w and grid_h else self_pos

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

