        if target is not None:
            return step_toward(self_pos, target)

        enemy = observation.get("opponent_position")
        if isinstance(enemy, (list, tuple)) and len(enemy) >= 2:
            return step_toward(self_pos, (enemy[0], enemy[1]))

        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = best_by(resources, lambda c: manhattan(c, self_pos))
    if target is not None:
        return step_toward(self_pos, target)

    enemy = observation.get("opponent_position")
